package com.novasky.holodeck;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.rule.ActivityTestRule;
import androidx.test.platform.app.InstrumentationRegistry;
import android.app.Instrumentation;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.Bitmap;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import java.io.*;import java.util.concurrent.*;import static org.junit.Assert.*;
@RunWith(AndroidJUnit4.class) public class PortalBloomTest {
 @Rule public ActivityTestRule<MainActivity> rule=new ActivityTestRule<>(MainActivity.class);
 Instrumentation inst(){return InstrumentationRegistry.getInstrumentation();} MainActivity a(){return rule.getActivity();}void ui(Runnable r){inst().runOnMainSync(r);}void click(int id){ui(()->{View v=a().findViewById(id);assertNotNull(v);v.performClick();});}
 String js(String code)throws Exception{CountDownLatch l=new CountDownLatch(1);String[] s={null};ui(()->a().getPlayer().evaluateJavascript(code,v->{s[0]=v;l.countDown();}));assertTrue(l.await(10,TimeUnit.SECONDS));return s[0];}JSONObject state()throws Exception{return new JSONObject(new JSONArray("["+js("JSON.stringify(PortalBloom.snapshot())")+"]").getString(0));}
 void ready()throws Exception{long end=SystemClock.uptimeMillis()+30000;while(SystemClock.uptimeMillis()<end){if("true".equals(js("!!window.PortalBloom && PortalBloom.snapshot().ready")))return;SystemClock.sleep(100);}fail("Portal Bloom did not become ready");}
 View text(View v,String target){if(v instanceof TextView&&((TextView)v).getText().toString().equals(target))return v;if(v instanceof ViewGroup){ViewGroup p=(ViewGroup)v;for(int i=0;i<p.getChildCount();i++){View found=text(p.getChildAt(i),target);if(found!=null)return found;}}return null;}
 void shot(String name)throws Exception{SystemClock.sleep(350);Bitmap b=inst().getUiAutomation().takeScreenshot();try(FileOutputStream f=new FileOutputStream(new File(a().getExternalFilesDir(null),name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 void shell(String command)throws Exception{try(ParcelFileDescriptor fd=inst().getUiAutomation().executeShellCommand(command);InputStream in=new FileInputStream(fd.getFileDescriptor())){byte[] b=new byte[1024];while(in.read(b)!=-1){}}}
 void event(int action,float x,float y,long down){ui(()->{MotionEvent e=MotionEvent.obtain(down,SystemClock.uptimeMillis(),action,x,y,0);a().getPlayer().dispatchTouchEvent(e);e.recycle();});}
 float[] coordinates(JSONObject s,double x,double y)throws Exception{JSONObject r=s.getJSONObject("canvas");float scale=a().getPlayer().getWidth()/(float)Double.parseDouble(js("innerWidth"));return new float[]{(float)(r.getDouble("x")+x*r.getDouble("width"))*scale,(float)(r.getDouble("y")+y*r.getDouble("height"))*scale};}
 @Test public void publishedPortalDownloadsAndPlaysOfflineOnUnchangedHost()throws Exception{
  long installed=a().getPackageManager().getPackageInfo(a().getPackageName(),0).lastUpdateTime;click(MainActivity.DISCOVER);long end=SystemClock.uptimeMillis()+90000;while(SystemClock.uptimeMillis()<end&&(a().store.catalog==null||a().busy))SystemClock.sleep(150);assertNotNull(a().store.catalog);assertTrue(a().store.available().stream().anyMatch(w->w.optString("id").equals("portal-bloom")));
  ui(()->{View title=text(a().getWindow().getDecorView(),"PORTAL BLOOM");assertNotNull("Published world visible in Discover",title);ViewGroup card=(ViewGroup)title.getParent();card.requestRectangleOnScreen(new android.graphics.Rect(0,0,card.getWidth(),card.getHeight()),true);});shot("20-portal-discover");
  ui(()->{View title=text(a().getWindow().getDecorView(),"PORTAL BLOOM");View v=text((View)title.getParent(),"Download world  ↓");assertNotNull("Native download control",v);v.performClick();});end=SystemClock.uptimeMillis()+90000;while(SystemClock.uptimeMillis()<end&&(a().store.installed("portal-bloom")==null||a().busy))SystemClock.sleep(150);assertNotNull(a().store.installed("portal-bloom"));shot("21-portal-installed-library");
  try{shell("cmd connectivity airplane-mode enable");shell("svc wifi disable");shell("svc data disable");click(MainActivity.OPEN_WORLD);ready();assertEquals("\"https://portal-bloom.holodeck.invalid\"",js("location.origin"));js("document.getElementById('begin').click()");
   for(int i=0;i<3;i++){JSONObject s=state(),n=s.getJSONArray("nodes").getJSONObject(i);float[] xy=coordinates(s,n.getDouble("x"),n.getDouble("y"));long down=SystemClock.uptimeMillis();event(0,xy[0],xy[1],down);int stone=i;end=SystemClock.uptimeMillis()+12000;while(SystemClock.uptimeMillis()<end&&state().getJSONArray("charges").getDouble(stone)<1)SystemClock.sleep(100);event(1,xy[0],xy[1],down);assertEquals(1,state().getJSONArray("charges").getDouble(i),0);}
   assertEquals("enter",state().getString("phase"));JSONObject s=state();float[] from=coordinates(s,.5,.86),to=coordinates(s,.5,.47);long down=SystemClock.uptimeMillis();for(int i=0;i<=12;i++){event(i==0?0:i==12?1:2,from[0]+(to[0]-from[0])*i/12,from[1]+(to[1]-from[1])*i/12,down);SystemClock.sleep(35);}end=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<end&&!state().getBoolean("completed"))SystemClock.sleep(100);assertTrue(state().getBoolean("completed"));shot("22-portal-completed-offline");click(MainActivity.EXIT);click(MainActivity.OPEN_WORLD);ready();assertTrue("Offline save survives exit and re-entry",state().getBoolean("completed"));shot("23-portal-saved-reentry");click(MainActivity.EXIT);assertEquals("No host APK reinstall for new world",installed,a().getPackageManager().getPackageInfo(a().getPackageName(),0).lastUpdateTime);
  }finally{shell("cmd connectivity airplane-mode disable");shell("svc wifi enable");shell("svc data enable");}
 }
}
